CREATE    PROCEDURE [synapse_ce].[usp_Insert_rics_surveyanswer]
AS
BEGIN
	INSERT INTO [synapse_ce].[rics_surveyanswer]
	(
		[createdby],
		[createdby_entitytype],
		[createdbyname],
		[createdbyyominame],
		[createdon],
		--[createdonbehalfby],
		--[createdonbehalfby_entitytype],
		--[createdonbehalfbyname],
		--[createdonbehalfbyyominame],
		[Id],
		--[importsequencenumber],
		[modifiedby],
		[modifiedby_entitytype],
		[modifiedbyname],
		[modifiedbyyominame],
		[modifiedon],
		--[modifiedonbehalfby],
		--[modifiedonbehalfby_entitytype],
		--[modifiedonbehalfbyname],
		--[modifiedonbehalfbyyominame],
		[overriddencreatedon],
		[ownerid],
		[ownerid_entitytype],
		[owneridname],
		--[owneridtype],
		[owneridyominame],
		[owningbusinessunit],
		[owningbusinessunit_entitytype],
		[owningbusinessunitname],
		--[owningteam],
		--[owningteam_entitytype],
		[owninguser],
		[owninguser_entitytype],
		[rics_additionalinformation],
		[rics_answer],
		[rics_answerstatus],
		[rics_evidencefilename],
		[rics_evidencepath],
		[rics_heading],
		[rics_heading_entitytype],
		[rics_headingname],
		[rics_name],
		--[rics_order],
		[rics_possibleanswer],
		[rics_possibleanswer_entitytype],
		--[rics_possibleanswerconfig],
		--[rics_possibleanswerconfig_entitytype],
		--[rics_possibleanswerconfigname],
		[rics_possibleanswername],
		[rics_question],
		[rics_question_entitytype],
		[rics_questionname],
		[rics_questionset],
		[rics_questionset_entitytype],
		--[rics_questionsetconfig],
		--[rics_questionsetconfig_entitytype],
		--[rics_questionsetconfigname],
		[rics_questionsetname],
		[rics_score],
		[rics_survey],
		[rics_survey_entitytype],
		[rics_surveyanswerid],
		[rics_surveyname],
		[rics_surveyresponse],
		[rics_surveyresponse_entitytype],
		[rics_surveyresponsename],
		[SinkCreatedOn],
		[SinkModifiedOn],
		[statecode],
		[statuscode],
		--[timezoneruleversionnumber],
		--[utcconversiontimezonecode],
		[versionnumber]
	)
	SELECT 
		stg.[createdby],
		stg.[createdby_entitytype],
		stg.[createdbyname],
		stg.[createdbyyominame],
		stg.[createdon],
		--stg.[createdonbehalfby],
		--stg.[createdonbehalfby_entitytype],
		--stg.[createdonbehalfbyname],
		--stg.[createdonbehalfbyyominame],
		stg.[Id],
		--stg.[importsequencenumber],
		stg.[modifiedby],
		stg.[modifiedby_entitytype],
		stg.[modifiedbyname],
		stg.[modifiedbyyominame],
		stg.[modifiedon],
		--stg.[modifiedonbehalfby],
		--stg.[modifiedonbehalfby_entitytype],
		--stg.[modifiedonbehalfbyname],
		--stg.[modifiedonbehalfbyyominame],
		stg.[overriddencreatedon],
		stg.[ownerid],
		stg.[ownerid_entitytype],
		stg.[owneridname],
		--stg.[owneridtype],
		stg.[owneridyominame],
		stg.[owningbusinessunit],
		stg.[owningbusinessunit_entitytype],
		stg.[owningbusinessunitname],
		--stg.[owningteam],
		--stg.[owningteam_entitytype],
		stg.[owninguser],
		stg.[owninguser_entitytype],
		stg.[rics_additionalinformation],
		stg.[rics_answer],
		stg.[rics_answerstatus],
		stg.[rics_evidencefilename],
		stg.[rics_evidencepath],
		stg.[rics_heading],
		stg.[rics_heading_entitytype],
		stg.[rics_headingname],
		stg.[rics_name],
		--stg.[rics_order],
		stg.[rics_possibleanswer],
		stg.[rics_possibleanswer_entitytype],
		--stg.[rics_possibleanswerconfig],
		--stg.[rics_possibleanswerconfig_entitytype],
		--stg.[rics_possibleanswerconfigname],
		stg.[rics_possibleanswername],
		stg.[rics_question],
		stg.[rics_question_entitytype],
		stg.[rics_questionname],
		stg.[rics_questionset],
		stg.[rics_questionset_entitytype],
		--stg.[rics_questionsetconfig],
		--stg.[rics_questionsetconfig_entitytype],
		--stg.[rics_questionsetconfigname],
		stg.[rics_questionsetname],
		stg.[rics_score],
		stg.[rics_survey],
		stg.[rics_survey_entitytype],
		stg.[rics_surveyanswerid],
		stg.[rics_surveyname],
		stg.[rics_surveyresponse],
		stg.[rics_surveyresponse_entitytype],
		stg.[rics_surveyresponsename],
		stg.[SinkCreatedOn],
		stg.[SinkModifiedOn],
		stg.[statecode],
		stg.[statuscode],
		--stg.[timezoneruleversionnumber],
		--stg.[utcconversiontimezonecode],
		stg.[versionnumber]	
	FROM [staging_ce].[rics_surveyanswer] stg
		LEFT JOIN [synapse_ce].[rics_surveyanswer] tgt
			ON tgt.[id] = stg.[id]
	WHERE tgt.[id] IS NULL
END
